package com.hospital.system.repository; import com.hospital.system.model.HospitalService; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; @Repository public class ServiceRepository { private final JdbcTemplate db; public ServiceRepository(JdbcTemplate db){this.db=db;} private final RowMapper<HospitalService> m=(r,n)->{HospitalService s=new HospitalService();s.serviceId=r.getLong("service_id");s.serviceName=r.getString("service_name");s.description=r.getString("description");s.price=r.getBigDecimal("price");s.active=r.getBoolean("active");return s;}; public List<HospitalService> all(){return db.query("SELECT * FROM hospital_service ORDER BY service_name",m);} public Optional<HospitalService> one(Long id){return db.query("SELECT * FROM hospital_service WHERE service_id=?",m,id).stream().findFirst();} public int add(HospitalService s){return db.update("INSERT INTO hospital_service(service_name,description,price,active) VALUES(?,?,?,?)",s.serviceName,s.description,s.price,s.active);} public int update(Long id,HospitalService s){return db.update("UPDATE hospital_service SET service_name=?,description=?,price=?,active=? WHERE service_id=?",s.serviceName,s.description,s.price,s.active,id);} public int delete(Long id){return db.update("DELETE FROM hospital_service WHERE service_id=?",id);} }
